      unlockPrice: 49, originalPrice: 99, publishTime: '今天',
      desc: '中辉建工集团成立于2014年，注册资本1亿元，持有建筑工程施工总承包一级等8项资质，年中标项目156个。现面向全国招募分公司合作，提供全套资质共享、投标支持、人员备案、财务独立、技术指导、培训支持六大扶持。',
      descMd: '## 企业概况\n\n中辉建工集团有限公司成立于 **2014年**，注册资本 **1亿元**，总部位于北京市朝阳区，是一家集建筑施工、市政公用、机电安装于一体的综合性建筑企业。\n\n## 资质实力\n\n- 建筑工程施工总承包 **一级**\n- 市政公用工程施工总承包 **二级**\n- 机电工程施工总承包 **二级**\n- 消防设施专业承包 **一级**\n- 年中标项目 **156个**（近3年平均）\n- 已加盟分公司 **28家**，覆盖华东、华北、华南\n\n## 六大扶持体系\n\n> 全套资质共享 · 投标支持 · 人员备案 · 财务独立 · 技术指导 · 培训支持\n\n1. **资质共享**：全套资质+安许+八大员+建造师\n2. **投标支持**：投标文件编制、保证金协助、业绩配合\n3. **人员备案**：注册建造师备案通道、技术负责人在岗\n4. **财务独立**：分公司独立银行账户、独立核算、独立开票\n5. **技术指导**：施工方案审核、安全质量监督\n6. **培训支持**：定期运营培训、政策解读、资源对接\n\n## 合作模式\n\n设立分公司，独立运营、独立核算、独立财务。合同期限 **3年起签**，可续签。管理费为项目金额的 **1%-2%**。\n\n现面向全国招募分公司合作伙伴，期待与您共创辉煌。',
