/* v3.1: mount mockFormData to window for direct page access */
window.mockFormData = window.MOCK.mockFormData;

/* 便捷查询 */
window.MOCK.supplyById = function (id) {
  return this.supplies.find(s => String(s.id) === String(id));
};
/* 用户状态解析：按 id 取定义，缺省回退到「注册会员」 */
window.MOCK.statusById = function (id) {
  var list = this.statuses || [];
  for (var i = 0; i < list.length; i++) { if (list[i].id === id) return list[i]; }
  return list[1] || { id: 'registered', label: '注册会员', level: 1, rights: [] };
};
/* 企业档案解析：按 id 取定义，缺省回退到第一家 */
window.MOCK.companyById = function (id) {
  var list = this.companies || [];
  for (var i = 0; i < list.length; i++) { if (list[i].id === id) return list[i]; }
  return list[0];
};
/* 个人用户档案解析：按 id 取定义，缺省回退到第一个人 */
window.MOCK.personById = function (id) {
  var list = this.persons || [];
  for (var i = 0; i < list.length; i++) { if (list[i].id === id) return list[i]; }
  return list[0];
};
/* 任一类明细按 id 取 (workDemands/cooperates/franchises/trades 共用) */
window.MOCK.detailOf = function (col, id) {
  var list = this[col] || [];
  for (var i = 0; i < list.length; i++) { if (String(list[i].id) === String(id)) return list[i]; }
  return null;
};
/* 统一目录查询：按 id 找到任意供需/机会明细 */
window.MOCK.listingById = function (id) {
  var list = this.catalog || [];
  for (var i = 0; i < list.length; i++) { if (String(list[i].id) === String(id)) return list[i]; }
  return null;
};
/* 按业务场景取 (可附方向过滤) */
window.MOCK.byBizType = function (bizKey, dir) {
  return (this.catalog || []).filter(function (x) { return x.bizKey === bizKey && (!dir || x.dir === dir); });
};
/* 按板块流取：match(供需匹配) / resource(资源机会) */
window.MOCK.byFlow = function (flow) {
  var keys = flow === 'resource' ? ['franchise', 'trade', 'personnel', 'talent'] : ['material', 'labor', 'equipment', 'cooperation', 'agency'];
  return (this.catalog || []).filter(function (x) { return keys.indexOf(x.bizKey) !== -1; });
};
/* 按企业入驻类型取模型（construction/agency/partner） */
window.MOCK.entryTypeById = function (id) {
  var t = this.business && this.business.entryTypes;
  return (t && t[id]) || null;
};
/* 按企业ID取该企业发布的全部招聘需求 */
window.MOCK.personnelsByCompany = function (companyId) {
  return (this.personnels || []).filter(function (x) { return x.companyId === companyId; });
};
/* 按证书类型取持证人才 */
window.MOCK.talentsByCertType = function (certType) {
  return (this.talents || []).filter(function (x) { return x.certType === certType; });
};